import * as webpush from 'jsr:@negrel/webpush'
import { createClient } from 'npm:@supabase/supabase-js@2'

const supabase = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)

function base64urlToBytes(value: string) {
  const padded = value.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (value.length % 4)) % 4)
  return Uint8Array.from(atob(padded), (char) => char.charCodeAt(0))
}

function bytesToBase64url(value: Uint8Array) {
  return btoa(String.fromCharCode(...value)).replaceAll('+', '-').replaceAll('/', '_').replaceAll('=', '')
}

async function importExistingVapidKeys() {
  const publicValue = Deno.env.get('VAPID_PUBLIC_KEY') || ''
  const privateValue = Deno.env.get('VAPID_PRIVATE_KEY') || ''
  const publicBytes = base64urlToBytes(publicValue)
  const privateBytes = base64urlToBytes(privateValue)
  if (publicBytes.length !== 65 || publicBytes[0] !== 4 || privateBytes.length !== 32) {
    throw new Error('VAPID keys must be a matching browser public key and 32-byte private key')
  }
  const publicJwk = {
    kty: 'EC', crv: 'P-256', x: bytesToBase64url(publicBytes.slice(1, 33)), y: bytesToBase64url(publicBytes.slice(33, 65)), ext: true,
  }
  const privateJwk = { ...publicJwk, d: bytesToBase64url(privateBytes) }
  return await webpush.importVapidKeys({ publicKey: publicJwk, privateKey: privateJwk })
}

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: { 'content-type': 'application/json', 'access-control-allow-origin': '*' },
})

Deno.serve(async (req) => {
  try {
    const subject = Deno.env.get('VAPID_SUBJECT') || ''
    if (!subject || !Deno.env.get('VAPID_PUBLIC_KEY') || !Deno.env.get('VAPID_PRIVATE_KEY')) {
      return json({ ok: false, error: 'VAPID secrets are missing in the Edge Function' }, 500)
    }
    const vapidKeys = await importExistingVapidKeys()
    const appServer = await webpush.ApplicationServer.new({ contactInformation: subject, vapidKeys })

    const payload = await req.json()
    const job = payload.record || payload
    if (!job?.id || !job?.teacher_id) return json({ ok: false, error: 'invalid job' }, 400)
    let subscriptionsQuery = supabase.from('push_subscriptions').select('id,endpoint,p256dh,auth').eq('teacher_id', job.teacher_id)
    subscriptionsQuery = job.student_id ? subscriptionsQuery.eq('student_id', job.student_id) : subscriptionsQuery.is('student_id', null)
    const { data: subscriptions, error } = await subscriptionsQuery
    if (error) throw error
    const message = JSON.stringify({ title: job.title || 'النخبة', body: job.body || 'لديك تنبيه جديد', url: job.url || '/' })
    let sent = 0
    let failed = 0
    const failures: Array<{ status?: number; message: string }> = []
    for (const subscription of subscriptions || []) {
      try {
        const subscriber = appServer.subscribe({ endpoint: subscription.endpoint, keys: { p256dh: subscription.p256dh, auth: subscription.auth } })
        await subscriber.pushTextMessage(message, { urgency: webpush.Urgency.High })
        sent += 1
      } catch (err) {
        failed += 1
        failures.push({
          status: err?.status ?? err?.statusCode,
          message: String(err?.message || err).slice(0, 180),
        })
        if (err?.status === 404 || err?.status === 410 || err?.statusCode === 404 || err?.statusCode === 410) {
          await supabase.from('push_subscriptions').delete().eq('id', subscription.id)
        }
      }
    }
    await supabase.from('push_notification_jobs').update({ processed_at: new Date().toISOString() }).eq('id', job.id)
    return json({ ok: failed === 0, sent, failed, subscriptionCount: subscriptions?.length || 0, failures })
  } catch (err) {
    console.error(err)
    return json({ ok: false, error: String(err?.message || err) }, 500)
  }
})
